import SwiftUI

struct RewardsHubView: View {

    @ObservedObject var gamificationViewModel: GamificationViewModel

    // MARK: - View State

    @State private var isClaimingWeeklyReward = false

    var body: some View {

        ScrollView {

            VStack(alignment: .leading, spacing: 20) {

                // MARK: - XP and Level

                GroupBox("Level Progress") {

                    VStack(alignment: .leading, spacing: 12) {

                        HStack {

                            Text("Level \(gamificationViewModel.level)")
                                .font(.title2)
                                .fontWeight(.bold)

                            Spacer()

                            Text("\(gamificationViewModel.totalXP) Total XP")
                                .foregroundColor(.secondary)
                        }

                        ProgressView(
                            value: gamificationViewModel.levelProgress
                        )
                        .tint(
                            gamificationViewModel.currentAppThemeColor ?? .purple
                        )

                        Text(
                            "\(gamificationViewModel.xpInLevel) / \(gamificationViewModel.xpNeededForLevel) XP toward Level \(gamificationViewModel.level + 1)"
                        )
                        .font(.caption)
                        .foregroundColor(.secondary)
                    }
                    .padding(.vertical, 8)
                }


                // MARK: - Rewards and Resources

                GroupBox("Your Rewards") {

                    VStack(spacing: 14) {

                        HStack {

                            Label(
                                "Crafting Fragments",
                                systemImage: "puzzlepiece.fill"
                            )

                            Spacer()

                            Text(
                                gamificationViewModel.craftingFragments.formatted()
                            )
                            .fontWeight(.semibold)
                        }

                        Divider()

                        HStack {

                            Label(
                                "Unopened Rare Packs",
                                systemImage: "gift.fill"
                            )

                            Spacer()

                            Text(
                                gamificationViewModel.unopenedRarePacks.formatted()
                            )
                            .fontWeight(.semibold)
                        }
                    }
                    .padding(.vertical, 8)
                }


                // MARK: - Weekly Challenge

                GroupBox("Weekly Challenge") {

                    VStack(alignment: .leading, spacing: 12) {

                        if let progress =
                            gamificationViewModel.weeklyChallengeProgress {

                            Text("Weekly Consistency Challenge")
                                .font(.headline)

                            HStack {

                                Text("Qualifying Days")

                                Spacer()

                                Text(
                                    "\(progress.qualifying_days) / \(progress.required_days)"
                                )
                                .fontWeight(.semibold)
                            }

                            ProgressView(
                                value: Double(progress.qualifying_days),
                                total: Double(progress.required_days)
                            )
                            .tint(.green)

                            Text(
                                "Reach your step goal or log food on 3 different days this week."
                            )
                            .font(.caption)
                            .foregroundColor(.secondary)

                            Divider()

                            Label(
                                "+50 XP",
                                systemImage: "star.fill"
                            )

                            Label(
                                "1 Rare Crystal Pack",
                                systemImage: "gift.fill"
                            )

                            if progress.claimed {

                                Label(
                                    "Reward Claimed!",
                                    systemImage: "checkmark.circle.fill"
                                )
                                .foregroundColor(.green)

                            } else if progress.completed {

                                Button {

                                    Task {

                                        isClaimingWeeklyReward = true

                                        defer {
                                            isClaimingWeeklyReward = false
                                        }

                                        await gamificationViewModel
                                            .claimWeeklyChallengeReward()
                                    }

                                } label: {

                                    if isClaimingWeeklyReward {

                                        ProgressView()

                                    } else {

                                        Text("Claim Weekly Reward")
                                    }
                                }
                                .buttonStyle(.borderedProminent)
                                .disabled(isClaimingWeeklyReward)

                            } else {

                                Text("Keep going to unlock your reward!")
                                    .font(.caption)
                                    .foregroundColor(.secondary)
                            }

                        } else {

                            ProgressView("Loading weekly challenge...")
                        }
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding(.vertical, 8)
                }


                // MARK: - Inventory Navigation

                Text("Inventory")
                    .font(.title2)
                    .fontWeight(.bold)

                NavigationLink {

                    RarePackInventoryView(
                        gamificationViewModel: gamificationViewModel
                    )

                } label: {

                    Label(
                        "Rare Pack Inventory",
                        systemImage: "gift.fill"
                    )
                }
                .buttonStyle(.borderedProminent)


                NavigationLink {

                    MaterialsInventoryView(
                        gamificationViewModel: gamificationViewModel
                    )

                } label: {

                    Label(
                        "Materials Inventory",
                        systemImage: "backpack.fill"
                    )
                }
                .buttonStyle(.borderedProminent)
                
                
                // MARK: - Cosmetic Inventory Navigation

                NavigationLink {

                    CosmeticInventoryView(
                        gamificationViewModel: gamificationViewModel
                    )

                } label: {

                    Label(
                        "Cosmetic Inventory",
                        systemImage: "shippingbox.fill"
                    )
                }
                .buttonStyle(.borderedProminent)


                // MARK: - Achievements Navigation

                Text("Achievements")
                    .font(.title2)
                    .fontWeight(.bold)

                NavigationLink {

                    AchievementsView(
                        gamificationViewModel: gamificationViewModel
                    )

                } label: {

                    Label(
                        "View Achievements",
                        systemImage: "medal.fill"
                    )
                }
                .buttonStyle(.borderedProminent)


                // MARK: - Cosmetic Crafting Navigation

                Text("Cosmetic Crafting")
                    .font(.title2)
                    .fontWeight(.bold)

                NavigationLink {

                    CosmeticCraftingView(
                        gamificationViewModel: gamificationViewModel
                    )

                } label: {

                    Label(
                        "Open Cosmetic Crafting",
                        systemImage: "hammer.fill"
                    )
                }
                .buttonStyle(.borderedProminent)

            } // Closes VStack
            .padding()

        } // Closes ScrollView
        
        .modifier(
            ProjectHealthThemeModifier(
                gamificationViewModel: gamificationViewModel
            )
        )

        .navigationTitle("Rewards Hub")
        .navigationBarTitleDisplayMode(.inline)


        // MARK: - Load Rewards

        .task {

            await gamificationViewModel.refreshWeeklyChallengeProgress()

            await gamificationViewModel.refreshUnopenedRarePacks()

            await gamificationViewModel.refreshMaterialsInventory()
        }


        // MARK: - Pull to Refresh

        .refreshable {

            await gamificationViewModel.refreshWeeklyChallengeProgress()

            await gamificationViewModel.refreshUnopenedRarePacks()

            await gamificationViewModel.refreshMaterialsInventory()
        }

    } // Closes body

} // Closes RewardsHubView
